            # up
            if i - 1 >= 0 and j < len(grid[i-1]) and grid[i-1][j] == 1 and (i-1, j) not in visited:
                stack.append((i-1, j))
            # down
            if i + 1 < rows and j < len(grid[i+1]) and grid[i+1][j] == 1 and (i+1, j) not in visited:
                stack.append((i+1, j))
