{"task_id": "T47", "code": "def solve(n: int, b: int) -> str:
    """Convert integer ``n`` to a string representation in base ``b`` (2 ≤ b ≤ 36).
    Digits 0‑9 are used for values 0‑9 and lowercase letters a‑z for 10‑35.
    A leading ``-`` is added for negative numbers.
    """
    if b < 2 or b > 36:
        raise ValueError("Base must be between 2 and 36")
    # Handle zero explicitly
    if n == 0:
        return "0"
    # Determine sign
    sign = "-" if n < 0 else ""
    n = abs(n)
    digits = []
    while n:
        n, rem = divmod(n, b)
        if rem < 10:
            digits.append(chr(ord('0') + rem))
        else:
            digits.append(chr(ord('a') + rem - 10))
    # The digits are collected least‑significant first
    return sign + ''.join(reversed(digits))
