{"task_id": "T38", "code": "def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses O(n log n) patience sorting method.
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find insertion point (first element >= x) for strictly increasing we need >
        idx = bisect.bisect_left(tails, x)
        # For strictly increasing, we should replace first element >= x with x
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)
}"}

