def solve(grid):
    """Count islands in a possibly ragged grid.
    A cell is considered land if its value is truthy (e.g., 1). Connectivity is 4-directional.
    Returns the number of connected components of land.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # up
            if i - 1 >= 0 and j < len(grid[i-1]) and grid[i-1][j]:
                if (i-1, j) not in visited:
                    stack.append((i-1, j))
            # down
            if i + 1 < rows and j < len(grid[i+1]) and grid[i+1][j]:
                if (i+1, j) not in visited:
                    stack.append((i+1, j))
            # left
            if j - 1 >= 0 and j-1 < len(grid[i]) and grid[i][j-1]:
                if (i, j-1) not in visited:
                    stack.append((i, j-1))
            # right
            if j + 1 < len(grid[i]) and grid[i][j+1]:
                if (i, j+1) not in visited:
                    stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

