def solve(grid):
    """Return the number of islands in a grid.
    An island is a group of horizontally or vertically adjacent cells whose value is truthy
    (e.g., 1, True). The grid may be empty, ragged, or contain non‑list rows; such rows are
    treated as having length 0. Cells that are falsy (e.g., 0, False, None) are water.
    """
    # Guard against non‑list inputs
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    visited = set()
    def is_land(r, c):
        # Return True if cell exists and is truthy
        if r < 0 or r >= rows:
            return False
        row = grid[r]
        if not isinstance(row, list):
            return False
        if c < 0 or c >= len(row):
            return False
        return bool(row[c])
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore four directions
            for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                ni, nj = i + di, j + dj
                if is_land(ni, nj) and (ni, nj) not in visited:
                    stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        if not isinstance(row, list):
            continue
        for j, val in enumerate(row):
            if bool(val) and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

