def solve(lst):
    """Flatten a nested list of integers.
    Returns a flat list of all integers in order.
    """
    result = []
    def helper(item):
        if isinstance(item, list):
            for sub in item:
                helper(sub)
        else:
            # Assuming non-list items are integers per spec
            result.append(item)
    helper(lst)
    return result

