def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins from the list `coins`. Return -1 if impossible.
    """
    if amount == 0:
        return 0
    # filter out non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # DP array, INF larger than any possible answer
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

